const html = $input.item.json.data;
const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
const extractedTitle = titleMatch ? titleMatch[1].trim() : "";

let text = html
  .replace(/<script[^>]*>.*?<\/script>/gis, "")
  .replace(/<style[^>]*>.*?<\/style>/gis, "")
  .replace(/<[^>]+>/g, " ")
  .replace(/\s+/g, " ")
  .trim();

if (text.length > 8000) {
  text = text.substring(0, 8000) + "...";
}

if (!text || text.length < 50) {
  throw new Error("No readable content");
}

return { title: extractedTitle, content: text };

parameters.text:
=Analyze the submitted learning material and create a structured summary.

Content:
{{ $json.content }}

parameters.jsCode:
const aiOutput = $input.item.json.output;
let parsed;
try {
  parsed = typeof aiOutput === "string" ? JSON.parse(aiOutput) : aiOutput;
} catch (e) {
  throw new Error("Invalid JSON from AI");
}

const extractContent = $("Extract Content").item.json;
const parseUpdate = $("Parse Telegram Update").item.json;

return {
  telegramUserId: parseUpdate.telegramUserId,
  chatId: parseUpdate.chatId,
  url: parseUpdate.argument,
  title: parsed.title || extractContent.title || "Untitled",
  content: extractContent.content,
  summary: parsed.summary || "",
  keyPointsJson: JSON.stringify(parsed.keyPoints || []),
  mainConceptsJson: JSON.stringify(parsed.mainConcepts || []),
  difficulty: parsed.difficulty || "beginner",
  addedDate: new Date().toISOString(),
  keyPoints: parsed.keyPoints || [],
  mainConcepts: parsed.mainConcepts || []
};

const parsed = $("Parse AI Response").item.json;
const saved = $input.item.json;

let message = `Title: ${parsed.title}\nDifficulty: ${parsed.difficulty}\n\nSummary:\n${parsed.summary}\n\nKey points:`;

parsed.keyPoints.forEach((point, i) => {
  message += `\n${i + 1}. ${point}`;
});

message += `\n\nMain concepts:`;
parsed.mainConcepts.forEach(concept => {
  message += `\n- ${concept}`;
});

return {
  chatId: parsed.chatId,
  message: message,
  materialId: saved.id
};

const callbackData = $json.callbackData || "";
const chatId = $json.chatId;
const telegramUserId = String($json.telegramUserId);

if (!callbackData.startsWith("quiz_material:")) {
  return [{ json: { ...$json, error: "Unsupported callback" } }];
}

const materialId = callbackData.split(":")[1];

return [
  {
    json: {
      ...$json,
      chatId,
      telegramUserId,
      materialId,
    },
  },
];

parameters.text:
=You are the Examiner agent for a Telegram learning assistant.

Generate exactly 5 multiple-choice quiz questions based only on the selected learning material.

Return ONLY valid JSON in this exact shape:

{
  "questions": [
    {
      "id": "Q1",
      "question": "...",
      "options": {
        "A": "...",
        "B": "...",
        "C": "...",
        "D": "..."
      },
      "correctAnswer": "A",
      "explanation": "..."
    },
    {
      "id": "Q2",
      "question": "...",
      "options": {
        "A": "...",
        "B": "...",
        "C": "...",
        "D": "..."
      },
      "correctAnswer": "B",
      "explanation": "..."
    }
  ]
}

Rules:
- Generate exactly 5 questions: Q1, Q2, Q3, Q4, Q5.
- Questions must be specific to the material.
- Do not reuse generic questions.
- Each question must have exactly 4 options: A, B, C, D.
- correctAnswer must be one of: A, B, C, D.
- explanation must explain why the correct answer is correct.
- Do not include markdown.
- Do not include text before or after the JSON.

Learning material:
Title: {{$json.title}}
Difficulty: {{$json.difficulty}}
Summary: {{$json.summary}}
Key points: {{$json.keyPointsJson}}
Main concepts: {{$json.mainConceptsJson}}
Content: {{$json.content}}

parameters.jsCode:
const raw = $json.output;

let parsed;

if (typeof raw === "string") {
  parsed = JSON.parse(raw);
} else {
  parsed = raw;
}

const questions = parsed.questions;

if (!Array.isArray(questions) || questions.length !== 5) {
  throw new Error("Examiner AI did not return exactly 5 questions");
}

const q = questions[0];

if (!q.options || !q.options.A || !q.options.B || !q.options.C || !q.options.D) {
  throw new Error("Question 1 does not have options A, B, C, and D");
}

if (!["A", "B", "C", "D"].includes(q.correctAnswer)) {
  throw new Error("Question 1 correctAnswer must be A, B, C, or D");
}

return [
  {
    json: {
      chatId: $("Parse Telegram Update").item.json.chatId,
      materialId: $("Parse Quiz Material Callback").item.json.materialId,

      questionId: q.id || "Q1",

      questionText:
        `Question 1/5:\n\n${q.question}\n\n` +
        `A) ${q.options.A}\n` +
        `B) ${q.options.B}\n` +
        `C) ${q.options.C}\n` +
        `D) ${q.options.D}`,

      optionA: q.options.A,
      optionB: q.options.B,
      optionC: q.options.C,
      optionD: q.options.D,

      correctAnswer: q.correctAnswer,
      explanation: q.explanation || "",

      questionsJson: JSON.stringify(questions),

      answerCallbackA: `answer:A:${q.correctAnswer}`,
      answerCallbackB: `answer:B:${q.correctAnswer}`,
      answerCallbackC: `answer:C:${q.correctAnswer}`,
      answerCallbackD: `answer:D:${q.correctAnswer}`,
    },
  },
];

const callbackData = $json.callbackData || $json.argument || "";

// New format:
// answer:<sessionId>:<questionIndex>:<selectedOption>:<correctOption>
// Example:
// answer:12:4:C:B

const parts = callbackData.split(":");

const sessionId = parts[1];
const questionIndex = Number(parts[2]);
const selected = parts[3];
const correct = parts[4];

if (!sessionId || Number.isNaN(questionIndex) || !selected || !correct) {
  return [
    {
      json: {
        ...$json,
        error: "invalid_answer_callback",
        replyText: "I could not read that answer. Please start a new quiz with /quiz.",
      },
    },
  ];
}

const isCorrect = selected === correct;

return [
  {
    json: {
      ...$json,
      sessionId,
      questionIndex,
      selected,
      correct,
      isCorrect,
      replyText: isCorrect
        ? "Correct! ✅"
        : `Incorrect. The correct answer is ${correct}.`,
    },
  },
];

const quizRow = $json;

// Data from previous nodes
const formatted = $("Format Question 1").item.json;
const parsedUpdate = $("Parse Telegram Update").item.json;

return [
  {
    json: {
      // fields needed by Send Question 1
      chatId: formatted.chatId,
      questionText: formatted.questionText,
      answerCallbackA: formatted.answerCallbackA,
      answerCallbackB: formatted.answerCallbackB,
      answerCallbackC: formatted.answerCallbackC,
      answerCallbackD: formatted.answerCallbackD,

      // quiz/session fields
      quizId: String(quizRow.id),
      materialId: String(formatted.materialId),
      telegramUserId: String(parsedUpdate.telegramUserId),
      questionsJson: formatted.questionsJson,
      currentQuestionIndex: 0,
      answersJson: "[]",
      status: "active",
      score: 0,
      startedDate: new Date().toISOString(),
      completedDate: null,
    },
  },
];

const session = $json;
const answer = $("Parse Answer Callback").item.json;

let answers = [];

try {
  answers = session.answersJson ? JSON.parse(session.answersJson) : [];
} catch (error) {
  answers = [];
}

const newAnswer = {
  questionIndex: Number(session.currentQuestionIndex || 0),
  selected: answer.selected,
  correct: answer.correct,
  isCorrect: answer.isCorrect,
  answeredAt: new Date().toISOString(),
};

answers.push(newAnswer);

const correctCount = answers.filter((a) => a.isCorrect).length;
const totalAnswered = answers.length;
const score = Math.round((correctCount / totalAnswered) * 100);

return [
  {
    json: {
      sessionId: session.id,
      quizId: session.quizId,
      materialId: session.materialId,
      telegramUserId: session.telegramUserId,

      currentQuestionIndex: Number(session.currentQuestionIndex || 0),
      nextQuestionIndex: Number(session.currentQuestionIndex || 0) + 1,

      answersJson: JSON.stringify(answers),
      score,
      status: "active",
      completedDate: null,

      chatId: answer.chatId,
      replyText: answer.replyText,
    },
  },
];

const sessionUpdate = $("Prepare Session Update").item.json;
const quiz = $json;

const nextIndex = Number(sessionUpdate.nextQuestionIndex);

let questions = [];

try {
  questions = quiz.questionsJson ? JSON.parse(quiz.questionsJson) : [];
} catch (error) {
  questions = [];
}

if (!Array.isArray(questions) || questions.length === 0) {
  throw new Error("No questions found in quizzes.questionsJson");
}

const q = questions[nextIndex];

if (!q) {
  throw new Error(`Question at index ${nextIndex} not found`);
}

return [
  {
    json: {
      chatId: sessionUpdate.chatId,
      quizId: sessionUpdate.quizId,
      sessionId: sessionUpdate.sessionId,
      materialId: sessionUpdate.materialId,
      questionIndex: nextIndex,
      questionId: q.id || `Q${nextIndex + 1}`,

      questionText:
        `Question ${nextIndex + 1}/5:\n\n${q.question}\n\n` +
        `A) ${q.options.A}\n` +
        `B) ${q.options.B}\n` +
        `C) ${q.options.C}\n` +
        `D) ${q.options.D}`,

      correctAnswer: q.correctAnswer,
      answerCallbackA: `answer:${sessionUpdate.sessionId}:${nextIndex}:A:${q.correctAnswer}`,
answerCallbackB: `answer:${sessionUpdate.sessionId}:${nextIndex}:B:${q.correctAnswer}`,
answerCallbackC: `answer:${sessionUpdate.sessionId}:${nextIndex}:C:${q.correctAnswer}`,
answerCallbackD: `answer:${sessionUpdate.sessionId}:${nextIndex}:D:${q.correctAnswer}`,
    },
  },
];

const sessionUpdate = $("Prepare Session Update").item.json;

let answers = [];

try {
  answers = sessionUpdate.answersJson ? JSON.parse(sessionUpdate.answersJson) : [];
} catch (error) {
  answers = [];
}

const total = 5;
const correctCount = answers.filter((a) => a.isCorrect).length;
const score = Math.round((correctCount / total) * 100);

const feedbackLines = answers.map((a, index) => {
  const mark = a.isCorrect ? "✅" : "❌";
  return `Q${index + 1}: ${mark} Your answer: ${a.selected}. Correct: ${a.correct}.`;
});

return [
  {
    json: {
      sessionId: sessionUpdate.sessionId,
      chatId: sessionUpdate.chatId,
      score,
      status: "completed",
      completedDate: new Date().toISOString(),
      finalText:
        `${sessionUpdate.replyText}\n\n` +
        `Quiz completed! 🎉\n\n` +
        `Score: ${score}% (${correctCount}/${total})\n\n` +
        `Feedback:\n${feedbackLines.join("\n")}`,
    },
  },
];

const items = $input.all();

const chatId = $("Parse Telegram Update").item.json.chatId;

const keyboard = items.map((item) => {
  const material = item.json;

  return [
    {
      text: material.title || `Material ${material.id}`,
      callback_data: `quiz_material:${material.id}`,
    },
  ];
});

const replyMarkup = {
  inline_keyboard: keyboard,
};

return [
  {
    json: {
      chatId,
      text: "Choose a material for your quiz:",
      replyMarkup,
      replyMarkupJson: JSON.stringify(replyMarkup),
    },
  },
];
